// Extract contact details using deterministic regex patterns
const items = $input.all();
const results = [];

for (const item of items) {
  // Get the normalized CV text
  const cvText = item.json.normalizedText || item.json.cv_text || '';

  if (!cvText) {
    results.push({
      json: {
        ...item.json,
        contact_info: {
          email: null,
          phone: null,
          linkedin: null
        }
      }
    });
    continue;
  }

  // Email regex pattern
  const emailRegex = /\b[A-Za-z0-9._%+-]+@[A-Za-z0-9.-]+\.[A-Z|a-z]{2,}\b/g;
  const emailMatches = cvText.match(emailRegex);
  const email = emailMatches ? emailMatches[0] : null;

  // Phone number regex patterns (supports various formats)
  const phoneRegex = /(?:\+?\d{1,3}[-.\s]?)?(?:\(?\d{1,4}\)?[-.\s]?)?\d{1,4}[-.\s]?\d{1,4}[-.\s]?\d{1,9}/g;
  const phoneMatches = cvText.match(phoneRegex);
  // Filter out numbers that are too short or too long
  const validPhones = phoneMatches ? phoneMatches.filter(p => {
    const digitsOnly = p.replace(/\D/g, '');
    return digitsOnly.length >= 10 && digitsOnly.length <= 15;
  }) : [];
  const phone = validPhones.length > 0 ? validPhones[0] : null;

  // LinkedIn URL regex pattern
  const linkedinRegex = /(?:https?:\/\/)?(?:www\.)?linkedin\.com\/in\/[A-Za-z0-9_-]+\/?/gi;
  const linkedinMatches = cvText.match(linkedinRegex);
  const linkedin = linkedinMatches ? linkedinMatches[0] : null;

  // Return structured contact info
  results.push({
    json: {
      ...item.json,
      contact_info: {
        email: email,
        phone: phone,
        linkedin: linkedin
      }
    }
  });
}

return results;

// Build final CV analysis response combining all available outputs

const inputItems = $input.all();

const response = {
  status: 'success',
  processing_time: null,
  profile_data: null,
  validation_report: null,
  structured_jd: null,
  match_score: null,
  technical_questions: null,
  hr_questions: null
};

function getNodeOutput(nodeName) {
  try {
    const item = $(nodeName).first();
    return item?.json?.output ?? item?.json ?? null;
  } catch (error) {
    return null;
  }
}

function getNodeJson(nodeName) {
  try {
    return $(nodeName).first()?.json ?? null;
  } catch (error) {
    return null;
  }
}

// Processing time
const receiveNode = getNodeJson('Receive CV and Job Description');
const startTime = receiveNode?.timestamp || Date.now();
response.processing_time = `${((Date.now() - startTime) / 1000).toFixed(2)}s`;

// CV parser
const cvParserOutput =
  getNodeOutput('Parse CV Parser Response') ||
  getNodeOutput('Parse CV Parser Response1');

if (cvParserOutput) {
  response.profile_data = cvParserOutput;
}

// Consistency / validation
const consistencyOutput = getNodeOutput('Parse Consistency Response');
if (consistencyOutput?.validation_report) {
  response.validation_report = consistencyOutput.validation_report;
} else if (consistencyOutput) {
  response.validation_report = consistencyOutput;
}

// JD parser
const jdParserOutput =
  getNodeOutput('Parse JD Parser Response') ||
  getNodeOutput('Parse Job Description Response');

if (jdParserOutput) {
  response.structured_jd = jdParserOutput;
}

// Matching
const matchingOutput = getNodeOutput('Parse Matching Response');
if (matchingOutput?.match_score) {
  response.match_score = matchingOutput.match_score;
} else if (matchingOutput) {
  response.match_score = matchingOutput;
}

// Questions from current merged input items
for (const item of inputItems) {
  const data = item.json?.output ?? item.json;

  if (data?.technical_questions) {
    response.technical_questions = data.technical_questions;
  }

  if (data?.hr_questions) {
    response.hr_questions = data.hr_questions;
  }
}

// Fallback: questions from named nodes, if they exist
if (!response.technical_questions) {
  const technicalOutput = getNodeOutput('Parse Technical Questions Response');
  response.technical_questions =
    technicalOutput?.technical_questions ?? technicalOutput ?? null;
}

if (!response.hr_questions) {
  const hrOutput = getNodeOutput('Parse HR Questions Response');
  response.hr_questions =
    hrOutput?.hr_questions ?? hrOutput ?? null;
}

// Contact info
const personalInfo = getNodeJson('Extract Personal Info');
const contactInfo = personalInfo?.contact_info;

if (contactInfo && response.profile_data) {
  response.profile_data.contact_info = contactInfo;
}

// Normalized skills
const skillsOutput = getNodeOutput('Parse Skills Response');

if (skillsOutput?.normalized_skills && response.profile_data) {
  response.profile_data.normalized_skills = skillsOutput.normalized_skills;
}

return [{ json: response }];

